import{_ as i,l,o as e,c as s,v as t,p as n,x as r,d,i as c,S as h}from"./chunks/framework.InCnrqk-.js";const A=JSON.parse('{"title":"轨道缺陷来源","description":"","frontmatter":{"title":"轨道缺陷来源","date":"2026-09-08T00:00:00.000Z","section":"litho"},"headers":[],"relativePath":"litho/track-defect-sources.md","filePath":"litho/track-defect-sources.md","lastUpdated":1789023840000}'),p={name:"litho/track-defect-sources.md"};function E(_,a,f,B,D,m){const o=l("Mermaid");return e(),s("div",null,[a[1]||(a[1]=t('<h1 id="轨道缺陷来源" tabindex="-1">轨道缺陷来源 <a class="header-anchor" href="#轨道缺陷来源" aria-label="Permalink to &quot;轨道缺陷来源&quot;">​</a></h1><div class="epigraph"><p>扫描仪写潜像；轨道贡献颗粒、条纹、溅射和升华。缺陷检测要先问在哪一段机台。</p><footer>—— 对照 track defect 分类：涂胶条纹、显影溅射、热板升华、传送刮伤</footer></div><p><a href="/litho/hotplate-uniformity">上一课</a>是热。缺口是颗粒与图案缺陷的<strong>轨道源</strong>，与 <a href="/litho/immersion-defects">浸没缺陷</a>、掩模缺陷分开记账。本课分类，不写检测算法。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p><a href="/litho/patterning-inspection-tools">图形化检测</a> 看见缺陷，不一定是曝光。涂胶条纹、气泡、 splatter、热板升华再沉积、机械手刮边、显影液干斑，都在 track。分错源会去调剂量或换掩模。</p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>按模块分账：涂胶杯（条纹、彗尾、 splatter）、热板（颗粒、升华）、显影碗（溅射、水印）、传送（刮伤、掉片边缘渣）。抽检：涂胶后、曝光前、显影后分步检测，才能定位。换胶与换杯清洗周期是缺陷率的一等参数。</p>',7)),(e(),n(h,null,{default:r(()=>[c(o,{id:"mermaid-19",class:"mermaid",graph:"flowchart%20TD%0A%20%20COAT%5B%22%E6%B6%82%E8%83%B6%E6%9D%AF%22%5D%20--%3E%20D1%5B%22%E6%9D%A1%E7%BA%B9%20%2F%20%E6%B0%94%E6%B3%A1%22%5D%0A%20%20HP%5B%22%E7%83%AD%E6%9D%BF%22%5D%20--%3E%20D2%5B%22%E5%8D%87%E5%8D%8E%E5%86%8D%E6%B2%89%E7%A7%AF%22%5D%0A%20%20DEV%5B%22%E6%98%BE%E5%BD%B1%22%5D%20--%3E%20D3%5B%22%E6%BA%85%E5%B0%84%20%2F%20%E6%B0%B4%E5%8D%B0%22%5D%0A%20%20ROB%5B%22%E4%BC%A0%E9%80%81%22%5D%20--%3E%20D4%5B%22%E5%88%AE%E4%BC%A4%22%5D%0A"})]),fallback:r(()=>[...a[0]||(a[0]=[d(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<p><span class="marginnote">胺污染是化学缺陷：CD 漂、不明欠曝。它走空气，不像颗粒走 SEM。监控要用化学传感器，不只缺陷机。</span></p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>液滴在旋涂中被气流撕碎成卫星点；升华物在较冷盖上凝结再掉。显影溅射把未溶胶块打到邻区。机制不同，清洗配方不同。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>下一课边缘曝光：有意用光清边，不是缺陷，但过曝会伤边缘器件。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>轨道缺陷按模块分账，分步检测定位。</li><li>不要默认缺陷来自扫描仪或掩模。</li><li>出处：track defect 工艺通识；检测课。</li></ul>',7))])}const k=i(p,[["render",E]]);export{A as __pageData,k as default};
